-- exmd16-2.hs: extended Minsky doubling (value x16, 2 cycles)
-- Start: (0, 0, 0). Goal: (0, 0, 1). The value reaches 16^2 = 256.
-- Generated by make-exmd.py.  Feed through hs2maze.py to obtain the maze.

exmd :: (Int, Int, Int) -> (Int, Int, Int)

-- Phase 0 (pc=0): y := 1
exmd (x, y,    0) = exmd (  x, y+1,    2)

-- Cycle 0 (pc=2): y -> x, x16
exmd (x, 0,    2) = exmd (  x,   0,   19)
exmd (x, y,    2) = exmd (  x, y-1,    3)
exmd (x, y,    3) = exmd (x+1,   y,    4)
exmd (x, y,    4) = exmd (x+1,   y,    5)
exmd (x, y,    5) = exmd (x+1,   y,    6)
exmd (x, y,    6) = exmd (x+1,   y,    7)
exmd (x, y,    7) = exmd (x+1,   y,    8)
exmd (x, y,    8) = exmd (x+1,   y,    9)
exmd (x, y,    9) = exmd (x+1,   y,   10)
exmd (x, y,   10) = exmd (x+1,   y,   11)
exmd (x, y,   11) = exmd (x+1,   y,   12)
exmd (x, y,   12) = exmd (x+1,   y,   13)
exmd (x, y,   13) = exmd (x+1,   y,   14)
exmd (x, y,   14) = exmd (x+1,   y,   15)
exmd (x, y,   15) = exmd (x+1,   y,   16)
exmd (x, y,   16) = exmd (x+1,   y,   17)
exmd (x, y,   17) = exmd (x+1,   y,   18)
exmd (x, y,   18) = exmd (x+1,   y,    2)

-- Cycle 1 (pc=19): x -> y, x16
exmd (0, y,   19) = exmd (  0,   y,   36)
exmd (x, y,   19) = exmd (x-1,   y,   20)
exmd (x, y,   20) = exmd (  x, y+1,   21)
exmd (x, y,   21) = exmd (  x, y+1,   22)
exmd (x, y,   22) = exmd (  x, y+1,   23)
exmd (x, y,   23) = exmd (  x, y+1,   24)
exmd (x, y,   24) = exmd (  x, y+1,   25)
exmd (x, y,   25) = exmd (  x, y+1,   26)
exmd (x, y,   26) = exmd (  x, y+1,   27)
exmd (x, y,   27) = exmd (  x, y+1,   28)
exmd (x, y,   28) = exmd (  x, y+1,   29)
exmd (x, y,   29) = exmd (  x, y+1,   30)
exmd (x, y,   30) = exmd (  x, y+1,   31)
exmd (x, y,   31) = exmd (  x, y+1,   32)
exmd (x, y,   32) = exmd (  x, y+1,   33)
exmd (x, y,   33) = exmd (  x, y+1,   34)
exmd (x, y,   34) = exmd (  x, y+1,   35)
exmd (x, y,   35) = exmd (  x, y+1,   19)

-- Drain (pc=36): DEC y to 0, then HALT
exmd (x, 0,   36) = (  x,   0,    1)
exmd (x, y,   36) = exmd (  x, y-1,   36)
